import numpy as np
from sim import Sim
from solve import PandaCupPolicy

sim=Sim(); pol=PandaCupPolicy(sim)
q_home=np.array([0.0,-0.5,0.0,-2.0,0.0,1.5,0.8])
pol.reset_targets_from_state(); pol.set_gripper(255)
for t in range(1500):
    a=(t+1)/1500
    pol.q_target=(1-a)*pol.q_target+a*q_home
    pol.apply_ctrl(); sim.step(1)

# Move above & down
for _ in range(2200):
    cup=sim.cup_position();
    pol.ik_update(np.array([cup[0],cup[1],0.60]))
    pol.set_gripper(255); pol.apply_ctrl(); sim.step(1)
for _ in range(1500):
    cup=sim.cup_position();
    pol.ik_update(np.array([cup[0],cup[1],0.54])); pol.apply_ctrl(); sim.step(1)
for _ in range(1700):
    cup=sim.cup_position();
    pol.ik_update(np.array([cup[0],cup[1],0.462])); pol.apply_ctrl(); sim.step(1)

# Close
for k in range(1800):
    cup=sim.cup_position();
    pol.ik_update(np.array([cup[0],cup[1],0.462]));
    pol.set_gripper(0); pol.apply_ctrl(); sim.step(1)

print('after close',sim.cup_position(),'mid',pol.finger_midpoint())

xy=pol.finger_midpoint()[:2].copy()
# Lift with monitoring every 400 steps
for i in range(3200):
    pol.ik_update(np.array([xy[0],xy[1],0.78])); pol.set_gripper(0); pol.apply_ctrl(); sim.step(1)
    if (i+1)%400==0:
        c=sim.cup_position();
        print('lift',i+1,'cup',c)

print('end lift cup',sim.cup_position(),'mid',pol.finger_midpoint())
