import numpy as np
from sim import Sim
from solve import PandaCupPolicy, evaluate_after_settle, _finger_cup_contact

sim=Sim(); pol=PandaCupPolicy(sim)
q_home=np.array([0.0,-0.5,0.0,-2.0,0.0,1.5,0.8])
pol.reset_targets_from_state(); pol.set_gripper(255)
for t in range(1500):
    a=(t+1)/1500
    pol.q_target=(1-a)*pol.q_target+a*q_home
    pol.apply_ctrl(); sim.step(1)

# descend to grasp with tracking
for z,steps in [(0.60,2200),(0.54,1500),(0.462,1700)]:
    for _ in range(steps):
        cup=sim.cup_position();
        pol.ik_update(np.array([cup[0],cup[1],z])); pol.set_gripper(255); pol.apply_ctrl(); sim.step(1)

# close while tracking
for k in range(2000):
    cup=sim.cup_position();
    pol.ik_update(np.array([cup[0],cup[1],0.462]));
    g=255-(255-0)*(k+1)/2000
    pol.set_gripper(g); pol.apply_ctrl(); sim.step(1)

# settle at grasp a bit
for _ in range(800):
    cup=sim.cup_position();
    pol.ik_update(np.array([cup[0],cup[1],0.462])); pol.set_gripper(0); pol.apply_ctrl(); sim.step(1)

print('after close+settle cup',sim.cup_position())

xy=pol.finger_midpoint()[:2].copy()
z0=pol.finger_midpoint()[2]
z1=0.68
held=True
for i in range(5000):
    z = z0 + (z1 - z0) * (i+1)/5000.0
    pol.ik_update(np.array([xy[0],xy[1],z])); pol.set_gripper(0); pol.apply_ctrl(); sim.step(1)
    if (i+1)%500==0:
        c=sim.cup_position();
        print('ramp',i+1,'cup_z',c[2])

# hold
for i in range(2500):
    pol.ik_update(np.array([xy[0],xy[1],z1])); pol.set_gripper(0); pol.apply_ctrl(); sim.step(1)

cup_z, contact_frac = evaluate_after_settle(sim, settle_steps=500)
print('after-settle',cup_z,contact_frac)
